import sys

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        root_u = self.find(u)
        root_v = self.find(v)
        if root_u != root_v:
            if self.rank[root_u] > self.rank[root_v]:
                self.parent[root_v] = root_u
            elif self.rank[root_u] < self.rank[root_v]:
                self.parent[root_u] = root_v
            else:
                self.parent[root_v] = root_u
                self.rank[root_u] += 1
            return True
        return False

def main():
    input = sys.stdin.readline
    n, m = map(int, input().split())
    a = list(map(int, input().split()))
    edges = []

    for i in range(m):
        x, y, w = map(int, input().split())
        edges.append((w, x - 1, y - 1))

    # Add direct edges between all vertices
    for i in range(n):
        edges.append((a[i] + a[i], i, n))

    # Sort edges by weight
    edges.sort()

    uf = UnionFind(n + 1)
    total_cost = 0
    for cost, u, v in edges:
        if uf.union(u, v):
            total_cost += cost

    print(total_cost)

if __name__ == "__main__":
    main()
